"""Offline controls: no APIs and no scientific scores generated by fixtures."""
import copy
from dataclasses import replace
import json
from pathlib import Path

import pytest

from jevbench.prompts import select_examples
from jevbench.types import Prediction,PreparedDataset,Row


@pytest.fixture
def module(monkeypatch):
    monkeypatch.syspath_prepend(str(Path(__file__).parents[1]/'scripts'))
    import prepare_review_controls
    return prepare_review_controls


@pytest.fixture
def jobs(module):
    result={}
    for name in module.DATASETS:
        classes=[f'class {i}' for i in range(module.N_CLASSES[name])]
        train=[Row(f'{name}-train-{c}-{i}',f'training feature {c} {i}',c) for c in range(len(classes)) for i in range(6)]
        test=[Row(f'{name}-test-{i}',f'heldout feature {i}',i%len(classes)) for i in range(module.FULL_TEST_ROWS[name])]
        dataset=PreparedDataset(name,classes,train,[],test,{'fixture':True})
        examples=select_examples(train,classes,4,42)
        predictions=[Prediction(row.id,(i+1)%len(classes)) for i,row in enumerate(test)]
        config={'model':module.SOURCE_MODEL,'revision':module.SOURCE_REVISION,'shots_per_class':4}
        result[name]={'dataset':dataset,'record':{'training_example_ids':[r.id for r in examples],
            'manifest_sha256':'original-manifest','run_id':f'{name}-source','config':config},
            'source':{'path':f'fixture/{name}','model':module.SOURCE_MODEL,'provider':'hf','hashes':{'run.json':'fixture'}},
            'examples':examples,'predictions':predictions}
    return result


def test_full_primary_and_operational_pilot_have_distinct_identity(module,jobs):
    full=module.build_plan(jobs)
    pilot=module.build_plan(jobs,limit_per_dataset=16)
    assert full['protocol']['case_count']==550 and len(full['requests'])==1714
    assert pilot['protocol']['case_count']==64 and len(pilot['requests'])==192
    assert full['protocol']['study_role']=='primary_full_fixed_holdouts'
    assert pilot['protocol']['study_role']=='operational_pilot_not_publication_evidence'
    assert full['protocol']['model_calls_performed']==0
    assert full['protocol']['budget_allocated_by_preparation_usd']=='0'
    assert 'Not established' in full['protocol']['funding']
    assert module.build_plan(jobs)==full
    with pytest.raises(ValueError):module.build_plan(jobs,limit_per_dataset=40)


def test_only_proposal_slot_changes_among_matched_requests(module,jobs):
    plan=module.build_plan(jobs,limit_per_dataset=16)
    groups={}
    for request in plan['requests']:
        groups.setdefault(request['case_id'],{})[request['arm']]=request
        assert set(request)=={'request_id','case_id','dataset','row_id','arm','proposal_value','donor_row_id','choices','prompt','prompt_sha256','execution_index','repeat_of_request_id'}
        assert module.SOURCE_MODEL not in request['prompt']
        assert 'probabilities' not in request['prompt'] and 'rationale' not in request['prompt']
        assert request['prompt_sha256']==module.sha(request['prompt'].encode())
    for arms in groups.values():
        assert set(arms)==set(module.PRIMARY_ARMS)
        request=arms['actual'];job=jobs[request['dataset']]
        row=next(r for r in job['dataset'].test if r.id==request['row_id'])
        prefix,suffix=module.prompt_parts(row,job['dataset'].labels,job['examples'])
        for r in arms.values():
            assert r['prompt']==prefix+json.dumps(r['proposal_value'])+suffix
        assert arms['no_proposal']['proposal_value']=='not provided'
        assert arms['no_proposal']['donor_row_id'] is None


def test_selection_shuffle_and_call_order_ignore_truth(module,jobs):
    before=module.build_plan(jobs,limit_per_dataset=16)
    changed=copy.deepcopy(jobs)
    for job in changed.values():
        job['dataset'].test=[replace(row,label='TEST_TARGET_MUST_NEVER_ENTER_REQUEST') for row in job['dataset'].test]
    after=module.build_plan(changed,limit_per_dataset=16)
    assert after==before
    assert 'TEST_TARGET_MUST_NEVER_ENTER_REQUEST' not in json.dumps(after)
    assert [r['execution_index'] for r in before['requests']]==list(range(192))
    ordered=sorted(before['requests'],key=lambda r:(module.rank('execution-order-v1',42,r['dataset'],r['row_id'],r['arm']),r['request_id']))
    assert ordered==before['requests']


def test_shuffle_preserves_counts_and_deranges_rows_not_necessarily_labels(module,jobs):
    # Constant proposals prove zero fixed row IDs do not imply changed labels.
    for job in jobs.values():
        for prediction in job['predictions']:prediction.label=0
    plan=module.build_plan(jobs,limit_per_dataset=16)
    for descriptor in plan['protocol']['datasets'].values():
        assert descriptor['actual_proposal_counts']==descriptor['shuffled_proposal_counts']=={'0':16}
        assert descriptor['donor_row_fixed_points']==0
        assert descriptor['unchanged_proposal_labels']==16
        assert set(descriptor['donor_mapping'])==set(descriptor['donor_mapping'].values())
        assert all(a!=b for a,b in descriptor['donor_mapping'].items())
    ids=['a','b','c','d']
    assert module.donor_mapping(ids,'fixture')==module.donor_mapping(list(reversed(ids)),'fixture')


def test_operational_selection_is_independent_of_proposals_and_source_order(module,jobs):
    before=module.build_plan(jobs,limit_per_dataset=16)
    for job in jobs.values():
        for p in job['predictions']:p.label=0
    after=module.build_plan(jobs,limit_per_dataset=16)
    for name in module.DATASETS:
        assert before['protocol']['datasets'][name]['selected_row_ids']==after['protocol']['datasets'][name]['selected_row_ids']
        rows=jobs[name]['dataset'].test
        assert [r.id for r in module.select_case_rows(rows,name,limit=16)]==[r.id for r in module.select_case_rows(list(reversed(rows)),name,limit=16)]
    assert [r['request_id'] for r in before['requests']]==[r['request_id'] for r in after['requests']]


def test_invalid_selected_source_is_not_silently_removed(module,jobs):
    name='wine';chosen=module.select_case_rows(jobs[name]['dataset'].test,name,limit=16)[0].id
    prediction=next(p for p in jobs[name]['predictions'] if p.row_id==chosen)
    prediction.label=None;prediction.error='source failure'
    with pytest.raises(ValueError,match='do not drop or replace'):
        module.build_plan(jobs,limit_per_dataset=16)


def test_manifest_preserves_original_source_identity_without_input_text(module,jobs):
    protocol=module.build_plan(jobs)['protocol']
    assert all(value['original_source_manifest_sha256']=='original-manifest' for value in protocol['datasets'].values())
    assert 'heldout feature' not in json.dumps(protocol)
    assert 'training feature' not in json.dumps(protocol)
    assert protocol['test_truth_in_requests'] is False
    assert protocol['primary_contrasts']==['actual_minus_no_proposal','actual_minus_shuffled']
    assert 'every declared true class' in protocol['balanced_accuracy_policy']


def test_freeze_verify_tamper_and_overwrite_guards(module,jobs,tmp_path,monkeypatch):
    monkeypatch.setattr(module,'source_hashes',lambda root=module.ROOT:{'fixture':'sourcehash'})
    monkeypatch.setattr(module,'load_jobs',lambda root=module.ROOT:jobs)
    plan=module.build_plan(jobs,limit_per_dataset=16)
    output=module.freeze_plan(plan,tmp_path/'plan')
    loaded=module.load_frozen_plan(output)
    assert loaded['requests']==plan['requests']
    with pytest.raises(ValueError,match='already exists'):module.freeze_plan(plan,output)
    (output/'requests.jsonl').write_bytes((output/'requests.jsonl').read_bytes()+b'{}\n')
    with pytest.raises(ValueError,match='file changed'):module.load_frozen_plan(output)


def test_revalidate_rejects_changed_sources_even_if_bundle_self_consistent(module,jobs,tmp_path,monkeypatch):
    monkeypatch.setattr(module,'source_hashes',lambda root=module.ROOT:{'fixture':'sourcehash'})
    monkeypatch.setattr(module,'load_jobs',lambda root=module.ROOT:jobs)
    output=module.freeze_plan(module.build_plan(jobs),tmp_path/'plan')
    jobs['sst2']['predictions'][0].label=(jobs['sst2']['predictions'][0].label+1)%2
    with pytest.raises(ValueError,match='freshly audited source data'):
        module.load_frozen_plan(output)


def test_freeze_is_explicit_and_dry_run_does_not_create_directory(module,jobs,tmp_path,monkeypatch,capsys):
    monkeypatch.setattr(module,'load_jobs',lambda root=module.ROOT:jobs)
    output=tmp_path/'absent'
    module.main(['--all-rows','--output',str(output)])
    assert not output.exists()
    status=json.loads(capsys.readouterr().out)
    assert status['status']=='dry_run_no_writes' and status['planned_requests']==1714
    assert status['funding_established'] is False



def test_serving_repeats_are_exact_prompt_controls_with_predeclared_label_blind_cases(module,jobs):
    plan=module.build_plan(jobs)
    protocol=plan['protocol'];requests=plan['requests'];by_id={r['request_id']:r for r in requests}
    assert protocol['primary_request_count']==1650 and protocol['repeat_request_count']==64
    assert protocol['serving_repeat_control']['enabled'] is True
    assert protocol['primary_contrasts']==['actual_minus_no_proposal','actual_minus_shuffled']
    for dataset in module.DATASETS:
        repeats=[r for r in requests if r['dataset']==dataset and r['arm']==module.REPEAT_ARM]
        assert len(repeats)==16 and len({r['case_id'] for r in repeats})==16
        candidates=[r for r in requests if r['dataset']==dataset and r['arm']=='no_proposal']
        selected=sorted(candidates,key=lambda r:(module.rank('repeat-selection-v1',42,dataset,r['case_id']),r['case_id']))[:16]
        assert set(r['case_id'] for r in repeats)==set(r['case_id'] for r in selected)
        for repeat in repeats:
            reference=by_id[repeat['repeat_of_request_id']]
            assert reference['arm']=='no_proposal'
            assert repeat['request_id']!=reference['request_id']
            assert repeat['case_id']==reference['case_id'] and repeat['row_id']==reference['row_id']
            assert repeat['prompt']==reference['prompt'] and repeat['choices']==reference['choices']
            assert repeat['prompt_sha256']==reference['prompt_sha256']
            assert repeat['proposal_value']=='not provided' and repeat['donor_row_id'] is None
    pilot=module.build_plan(jobs,limit_per_dataset=16)
    assert pilot['protocol']['repeat_request_count']==0
    assert pilot['protocol']['serving_repeat_control']['enabled'] is False
    assert len(pilot['requests'])==192
